<template>
<el-dialog v-model="visible" :title="opening?'登记期初库存':'添加'+(kind==='OUT'?'出库':kind==='IN'?'入库':'还库')+'工单'" class="warehouse-dialog" :class="{'production-out-dialog':form.type==='PRODUCTION_OUT'}" :width="form.type==='PRODUCTION_OUT'?'min(1188px,96vw)':'min(900px,94vw)'" top="5vh" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy">
