 <el-form-item label="仓库/库房" required><el-select v-model="form.warehouseId" fit-input-width @change="form.lines=[]"><el-option v-for="o in warehouses" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <el-form-item v-for="field in peopleFields" :key="field.key" :label="field.label" :required="field.required"><el-select v-model="form[field.key]" :multiple="field.key==='operatorIds'" fit-input-width clearable><el-option v-for="o in people" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item>
 <div class="line-toolbar"><span><span class="required-mark">*</span>物料清单</span><el-button class="blue" :disabled="!form.factoryId||!form.warehouseId" @click="editLine()">添加</el-button><el-button class="orange" :disabled="selected.length!==1" @click="editLine(selected[0])">编辑</el-button><el-button class="red" :disabled="!selected.length" @click="removeLines">删除</el-button><el-button v-if="can('metal:warehouse-order:import')" class="blue" @click="download">模板下载</el-button><el-button v-if="can('metal:warehouse-order:import')" class="blue" :disabled="!form.factoryId||!form.warehouseId" @click="fileRef?.click()">导入模板</el-button><input ref="fileRef" type="file" accept=".xlsx" hidden @change="importFile"/></div>
 <el-table :data="form.lines" border @selection-change="selected=$event"><el-table-column type="selection" width="42"/><el-table-column v-for="c in lineColumns" :key="c.key" :label="c.label" :prop="c.key" :min-width="c.width||90"/><el-table-column label="操作" width="140" align="center"><template #default="{row}"><div class="material-line-actions"><el-button class="detail-edit-button" size="small" @click="editLine(row)">编辑</el-button><el-button class="detail-delete-button" size="small" @click="form.lines.splice(form.lines.indexOf(row),1)">删除</el-button></div></template></el-table-column></el-table>
 <template v-if="form.batchId&&['RAW_RETURN','FINISHED_IN','SEMI_IN'].includes(form.type)"><el-form-item label="本批次结算"><el-checkbox v-model="form.settle" :disabled="!can('metal:process-batch:settle')">全部领回料已登记，确认结算</el-checkbox></el-form-item><el-form-item v-if="form.settle" label="实际完成数量" required><el-input v-model.number="form.completedQuantity" inputmode="numeric"/></el-form-item></template>
 </el-form><template #footer><el-button :disabled="busy" @click="visible=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">确认</el-button></template>
</el-dialog>
<el-dialog v-model="lineVisible" title="物料明细" class="warehouse-line-dialog" width="min(620px,94vw)" :close-on-click-modal="false"><el-form label-width="120px">
<el-form-item v-if="opening" label="分类"><el-select v-model="line.category" @change="line.referenceId='' "><el-option label="原材料" value="RAW"/><el-option label="成品" value="FINISHED"/><el-option label="半成品" value="SEMI"/></el-select></el-form-item>
<el-form-item required :label="out?'库存物料':returning?'原出库明细':'物料/产品'"><el-select v-model="line.choiceId" filterable fit-input-width @change="choiceChanged"><el-option v-for="o in choices" :key="o.id" :label="(o.code?o.code+' / ':'')+o.name+' [ID:'+o.id+']'" :value="o.id"/></el-select></el-form-item>
<el-form-item v-if="!out&&!returning&&line.category!=='RAW'&&!form.batchId" label="批次号"><el-input v-model="line.batchNo" placeholder="可不填，系统生成" maxlength="160"/></el-form-item><el-form-item v-if="line.category==='RAW'" label="毛重(g)" :error="weightError('grossWeight')"><el-input v-model="line.grossWeight" inputmode="decimal" maxlength="21" placeholder="请输入数字，最多6位小数" @input="deriveNet"/></el-form-item><el-form-item v-if="line.category==='RAW'" label="杂质(g)" :error="weightError('impurity')"><el-input v-model="line.impurity" inputmode="decimal" maxlength="21" placeholder="请输入数字，最多6位小数" @input="deriveNet"/></el-form-item><el-form-item label="实测净重(g)" :error="weightError('netWeight')" required><el-input v-model="line.netWeight" inputmode="decimal" maxlength="21" placeholder="请输入数字，最多6位小数"/></el-form-item><el-form-item v-if="line.category!=='RAW'" label="数量(件)" required><el-input v-model.number="line.quantity" inputmode="numeric"/></el-form-item><el-form-item v-if="line.category!=='RAW'" label="纯度(%)"><el-input v-model="line.purity" inputmode="decimal"/></el-form-item><el-form-item label="单位名称"><el-input v-model="line.organization" maxlength="100"/></el-form-item><el-form-item label="用途"><el-input v-model="line.purpose" maxlength="200"/></el-form-item><el-form-item label="备注"><el-input v-model="line.remark" maxlength="500"/></el-form-item></el-form><template #footer><el-button @click="lineVisible=false">取消</el-button><el-button type="primary" @click="confirmLine">确认</el-button></template></el-dialog>

</template>
<script setup lang="ts">
