const emit=defineEmits(['saved']),visible=ref(false),busy=ref(false),loading=ref(false),kind=ref('OUT'),opening=ref(false),form=reactive<Row>({}),factories=ref<Row[]>([]),warehouses=ref<Row[]>([]),people=ref<Row[]>([]),orders=ref<Row[]>([]),batches=ref<Row[]>([]),stocks=ref<Row[]>([]),materials=ref<Row[]>([]),products=ref<Row[]>([]),sources=ref<Row[]>([]),items=ref<Row[]>([]),itemId=ref(''),processId=ref(''),selected=ref<Row[]>([]),lineVisible=ref(false),line=reactive<Row>({}),lineIndex=ref(-1),fileRef=ref<HTMLInputElement>();
const user=useUserStore(),admin=computed(()=>String(user.id)==='1'),can=(p:string)=>user.permissions.includes('*:*:*')||user.permissions.includes(p),types=computed(()=>opening.value?['OPENING']:kind.value==='OUT'?['PRODUCTION_OUT','PRODUCT_OUT','EXCHANGE_OUT','SEMI_OUT']:kind.value==='IN'?['RAW_IN','FINISHED_IN','SEMI_IN']:['RAW_RETURN','PRODUCT_RETURN']),productionAllowed=computed(()=>['PRODUCTION_OUT','RAW_RETURN','FINISHED_IN','SEMI_IN'].includes(form.type)&&!opening.value),out=computed(()=>kind.value==='OUT'&&!opening.value),returning=computed(()=>kind.value==='RET'&&!opening.value),steps=computed(()=>items.value.find(o=>o.id===itemId.value)?.plans??[]),filteredBatches=computed(()=>batches.value.filter(o=>(!form.workOrderId||o.workOrderId===form.workOrderId)&&(!itemId.value||o.itemId===itemId.value)&&(!processId.value||o.processId===processId.value))),peopleFields=computed(()=>[{key:'operatorIds',label:'经办人',required:form.type!=='PRODUCTION_OUT'},...(out.value?[{key:'recipientId',label:'领用人',required:['PRODUCTION_OUT','SEMI_OUT'].includes(form.type)}]:[{key:'inspectorId',label:'验收人',required:false}]),{key:'keeperId',label:'仓管员',required:true},{key:'reviewerId',label:'审核人',required:false}]);
const choices=computed(()=>out.value?stocks.value.filter(o=>o.warehouseId===form.warehouseId&&(form.type==='PRODUCTION_OUT'?['RAW','SEMI'].includes(o.category):o.category===categoryForType())):returning.value?sources.value.filter(o=>form.type==='RAW_RETURN'?o.type==='PRODUCTION_OUT'&&o.category==='RAW'&&o.batchId===form.batchId:o.type==='PRODUCT_OUT'):line.category==='RAW'?materials.value:products.value);
const boundBatch=computed(()=>batches.value.find(b=>b.workOrderId===form.workOrderId&&b.itemId===itemId.value&&b.processId===processId.value));watch(boundBatch,b=>{form.batchId=b?.id||'';form.batchVersion=b?.version});
const lineColumns=computed(()=>{const fields=[{label:'物料编码',key:'code'},{label:'单位名称',key:'organization'},{label:'品名/类别',key:'name',width:120},{label:'规格型号',key:'specification'}];const raw=['PRODUCTION_OUT','RAW_IN','RAW_RETURN','EXCHANGE_OUT'].includes(form.type)||(opening.value&&line.category==='RAW');if(!raw)fields.splice(1,0,{label:'批次号',key:'batchNo',width:140});if(raw)fields.push({label:'毛重',key:'grossWeight'},{label:'杂质',key:'impurity'});fields.push({label:'净重(g)',key:'netWeight'});if(!raw||form.lines.some((r:Row)=>r.category!=='RAW'))fields.push({label:'数量',key:'quantity'});if(!raw)fields.push({label:'纯度%',key:'purity'},{label:'单位',key:'unit'});if(raw)fields.push({label:'用途',key:'purpose'});fields.push({label:'备注',key:'remark'});return fields})
