async function open(tab='OUT',initial=false,category='RAW'){opening.value=initial;kind.value=tab;for(const k of Object.keys(form))delete form[k];Object.assign(form,{requestId:createUUID(),factoryId:'',warehouseId:'',type:initial?'OPENING':tab==='OUT'?'PRODUCTION_OUT':tab==='IN'?(category==='FINISHED'?'FINISHED_IN':category==='SEMI'?'SEMI_IN':'RAW_IN'):'RAW_RETURN',orderDate:new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date()),lines:[],operatorIds:[],settle:false});form.orderNo=(await request({url:'/metal/warehouse-order/number/reserve',method:'post',data:{requestId:form.requestId,kind:initial?'ADJ':tab}})).data;itemId.value='';processId.value='';items.value=[];selected.value=[];factories.value=(await warehouseOptions('factories')).data;form.factoryId=!admin.value?factories.value[0]?.id:'';line.category=category;if(form.factoryId)await reloadOptions();else{warehouses.value=[];people.value=[];orders.value=[];batches.value=[];stocks.value=[];materials.value=[];products.value=[];sources.value=[]}visible.value=true}
