async function batchChanged(){const b=batches.value.find(o=>o.id===form.batchId);form.batchVersion=b?.version;form.lines=[];form.settle=false;if(b){form.workOrderId=b.workOrderId;items.value=(await orderDetail(b.workOrderId)).data.items;itemId.value=b.itemId;processId.value=b.processId}}
